export default function BootScreen() {
  const [isVisible, setIsVisible] = useState(() => !safeSessionStorage.getItem('booted'));
  const [showPrompt, setShowPrompt] = useState(false);
  useEffect(() => {
    if (!isVisible && !showPrompt) return;
    // Lock scroll during boot
    document.body.style.overflow = "hidden";
    if (typeof window !== "undefined") {
        scrollToTop(true);
    }
    const isLighthouse = typeof navigator !== 'undefined' && /Lighthouse|bot|crawler|spider/i.test(navigator.userAgent);
    const bootDuration = isLighthouse ? 0 : 3500;
    // Total boot time
    const timer = setTimeout(() => {
      setIsVisible(false);
      safeSessionStorage.setItem('booted', 'true');
      // Only show theme prompt once per session
      if (!isLighthouse && !safeSessionStorage.getItem('themePromptShown')) {
        setShowPrompt(true);
        safeSessionStorage.setItem('themePromptShown', 'true');
      } else {
        document.body.style.overflow = "";
      }
    }, bootDuration);
    return () => clearTimeout(timer);
  }, []);
  if (!isVisible && !showPrompt) return null;
  return (
    <>
      <AnimatePresence>
        {isVisible && (
          <motion.div
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.5, ease: "easeInOut" }}
          >
            {/* Logo animation container */}
            <motion.div
              initial={{ scale: 0.95, opacity: 0, filter: "blur(5px)" }}
              animate={{ scale: 1, opacity: 1, filter: "blur(0px)" }}
              transition={{ duration: 1, ease: "easeOut" }}
            >
              <img 
                src="/brand/tasc-logo-dark.png" 
                alt="TASC Boot Logo" 
              />
              {/* Fake cyan scanline sweep effect overlaying the logo, recreating the video energy pulse */}
              <motion.div
                initial={{ left: "-40%", opacity: 0 }}
                animate={{ left: "120%", opacity: 1 }}
                transition={{ duration: 2, ease: "easeInOut", delay: 0.8 }}
                style={{ mixBlendMode: 'overlay' }}
              />
            </motion.div>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 1.5, duration: 0.5 }}
            >
              <div >
                <motion.div
                  initial={{ x: "-100%" }}
                  animate={{ x: "100%" }}
                  transition={{ duration: 1.5, ease: "easeInOut", repeat: Infinity }}
                />
              </div>
              <span >
                INITIALIZING SYSTEMS...
              </span>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
      {showPrompt && <ThemePrompt onComplete={() => setShowPrompt(false)} />}
    </>
  );
}


