export const ThemePrompt = ({ onComplete }: { onComplete: () => void }) => {
  const [timeLeft, setTimeLeft] = useState(3);
  const [isVisible, setIsVisible] = useState(true);
  useEffect(() => {
    // Lock scroll during prompt
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = "";
    };
  }, []);
  useEffect(() => {
    if (timeLeft <= 0) {
      handleAutoTheme();
      return;
    }
    const countdown = setInterval(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);
    return () => clearInterval(countdown);
  }, [timeLeft]);
  const setTheme = (isLight: boolean) => {
    if (isLight) {
      document.documentElement.classList.add('light');
      safeLocalStorage.setItem('theme', 'light');
    } else {
      document.documentElement.classList.remove('light');
      safeLocalStorage.setItem('theme', 'dark');
    }
    // Dispatch event so Header can catch the change
    window.dispatchEvent(new Event('theme-changed'));
    closePrompt();
  };
  const handleAutoTheme = () => {
    setTheme(false); // Default to Dark mode
  };
  const closePrompt = () => {
    setIsVisible(false);
    document.body.style.overflow = "";
    setTimeout(onComplete, 500); // give time for exit animation
  };
  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
        >
          <motion.div 
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
          >
            <div >
              [ Select Interface Mode ]
            </div>
            <div >
              <button
                onClick={() => setTheme(true)}
              >
                <Sun  size={32} />
                <span >LIGHT</span>
              </button>
              <button
                onClick={() => setTheme(false)}
              >
                <Moon  size={32} />
                <span >DARK</span>
              </button>
            </div>
            <div >
              You can switch later using the icon in the menu bar.
            </div>
            <div >
              <motion.div
                initial={{ width: "100%" }}
                animate={{ width: "0%" }}
                transition={{ duration: 3, ease: "linear" }}
              />
            </div>
            <div >
              Auto selection in {timeLeft}s (Defaulting to Dark)
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};


